   pub struct KnownProfiles { max: usize, ids: Mutex<IndexMap<String, String>> }

   impl KnownProfiles {
       /// At most `max` users, and at least one.
       pub fn new(max: usize) -> KnownProfiles {
           KnownProfiles { max: max.max(1), ids: Mutex::new(IndexMap::new()) }
       }
       /// The profile id `user_id` was last resolved to, while it is held.
       pub fn get(&self, user_id: &str) -> Option<String> { lock(&self.ids).get(user_id).cloned() }
       /// Remembers that `user_id` resolved to `profile_id`; a new user past the bound drops the
       /// one remembered longest ago.
       pub fn remember(&self, user_id: &str, profile_id: &str) {
           let mut ids = lock(&self.ids);
           if let Some(held) = ids.get_mut(user_id) {
               if held.as_str() != profile_id { *held = profile_id.to_string(); }
               return;
           }
           while ids.len() >= self.max { ids.shift_remove_index(0); }
           ids.insert(user_id.to_string(), profile_id.to_string());
       }
       /// How many users are held, so a test can see the bound.
       pub fn size(&self) -> usize { lock(&self.ids).len() }
   }

